\begin{table*}[t]
\centering
\caption{Representative approaches and their main focus}
\label{tab:related}
\footnotesize
\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}lll@{}}
\toprule
\textbf{Work} & \textbf{Selection} & \textbf{Main question} \\
\midrule
Anomaly extraction~\cite{silveira2010urca,brauckhoff2009extraction} & Over-represented feature values & Which values explain an anomaly? \\
PacketScore~\cite{kim2006packetscore} & Packets scored against a nominal profile & Which packets to drop under overload? \\
JA3 report~\cite{kobayashi2024ja3} & HTTPS traffic using JA3 & Can JA3 mitigate HTTPS floods in a security operations center? \\
This work & New or over-represented JA4 at the endpoint & What coverage and collateral does filtering yield? \\
\bottomrule
\end{tabular*}
\end{table*}

\begin{table}[!ht]
\centering
\caption{The calibrated configurations on production traffic}
\label{tab:configs}
\scriptsize
\setlength{\tabcolsep}{3pt}
\begin{tabular}{@{}llll@{}}
\toprule
\textbf{Configuration} & \textbf{Trigger} & \textbf{Scope} & \textbf{Fleets} \\
\midrule
\multicolumn{4}{@{}l}{\textit{Fixed on the development days: the primary (test 1), then two references}} \\
Primary                       & origins        & binomial $\cup$ novelty    & exempt \\
$z$-score                     & origins        & $z >$ its p99              & no \\
Base rule                     & $\Omega$       & binomial                   & no \\
\rowcolor[gray]{0.90}
\multicolumn{4}{@{}l}{\textit{Pre-registered after the held-out day: the novelty rule and two arms (tests 2 and 3)}} \\
\rowcolor[gray]{0.90}
Novelty rule                  & none           & novelty                    & no \\
\rowcolor[gray]{0.90}
Beta-binomial arm$^{\dagger}$ & seasonal       & beta-bin.\ $\cup$ novelty  & no \\
\rowcolor[gray]{0.90}
No-trigger arm, E1 only       & none           & binomial $\cup$ novelty    & exempt \\
\multicolumn{4}{@{}l}{\textit{Post hoc}} \\
Two-path rule                 & none / origins & novelty / binomial         & exempt \\
\bottomrule
\end{tabular}

\vspace{2pt}
\begin{minipage}{\linewidth}\footnotesize The held-out day's protocol fixed only the primary and the base rule. $^{\dagger}$Cross-fitted. $\Omega$: an earlier design, mostly counting volume (Appendix~\ref{app:window}).\end{minipage}
\end{table}

